using System.Reflection.Metadata;using System.Reflection.PortableExecutable;using System.Security.Cryptography;using System.Reflection.Metadata.Ecma335;
var path=@"C:\Program Files (x86)\Steam\steamapps\common\7 Days To Die\7DaysToDie_Data\Managed\Assembly-CSharp.dll";using var file=File.OpenRead(path);using var pe=new PEReader(file);var reader=pe.GetMetadataReader();Console.WriteLine("DLL "+Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(path))));Console.WriteLine("MVID "+reader.GetGuid(reader.GetModuleDefinition().Mvid));foreach(var handle in reader.TypeDefinitions){var t=reader.GetTypeDefinition(handle);if(reader.GetString(t.Name)!="ConnectionManager")continue;foreach(var mh in t.GetMethods()){var method=reader.GetMethodDefinition(mh);if(reader.GetString(method.Name)!="ProcessPackages")continue;Console.WriteLine("ProcessPackages IL "+Convert.ToHexString(SHA256.HashData(pe.GetMethodBody(method.RelativeVirtualAddress).GetILBytes())));}}